import json, os
from ghidra.app.decompiler import DecompInterface
prog = currentProgram
outdir = "/Users/yuluo/Desktop/game/games_test/tiny-glade/crates/country-core/recovery/agent-team/reports/re-analysis/hardpoints-ecstate/evidence/decomp"
addrs = {"0x14229a7f0": "show_color_options_14229a7f0", "0x142291230": "color_menu_142291230"}
results = {}
d = DecompInterface()
try:
    d.openProgram(prog)
    for a, name in addrs.items():
        monitor.checkCancelled()
        addr = prog.getAddressFactory().getAddress(a)
        f = prog.getFunctionManager().getFunctionAt(addr)
        if f is None:
            results[a] = "absent"
            continue
        res = d.decompileFunction(f, 600, monitor)
        if res.decompileCompleted():
            code = res.getDecompiledFunction().getC()
            path = os.path.join(outdir, name + "_full.c")
            open(path, "w").write(code)
            results[a] = {"ok": True, "path": path, "len": len(code)}
        else:
            results[a] = {"ok": False, "err": str(res.getErrorMessage())}
finally:
    d.dispose()
print(json.dumps(results))
